    expect(node).toBeDefined();
    expect(node?.replies.map((r) => r.id)).toEqual([reply.id]);
  });

  it("orders replies oldest first inside a thread", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Ordering thread" }),
      north.userIds.owner,
      number,
    );

    const top = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Parent",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    const first = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "First reply",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );
    const second = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Second reply",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );

    const thread = await commentRepo.listThread(north.org.id, issue.id);
    const node = thread.find((n) => n.comment.id === top.id);

    expect(node?.replies.map((r) => r.id)).toEqual([first.id, second.id]);
  });

  it("hides soft-deleted comments from the default listing", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Soft delete listing" }),
      north.userIds.owner,
      number,
    );
    const comment = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Will be deleted",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    await commentRepo.archiveComment(north.org.id, comment.id);

    const page = await commentRepo.listComments({
      orgId: north.org.id,
      issueId: issue.id,
      limit: 25,
      cursor: null,
      includeArchived: false,
    });

    expect(page.items.map((row) => row.id)).not.toContain(comment.id);
  });

  it("keeps live replies when their parent is soft-deleted", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Deleted parent" }),
      north.userIds.owner,
      number,
    );

    const top = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Parent to delete",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    const reply = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Still alive",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );
    await commentRepo.archiveComment(north.org.id, top.id);

    const thread = await commentRepo.listThread(north.org.id, issue.id);
    const node = thread.find((n) => n.comment.id === top.id);

    expect(node).toBeDefined();
    expect(node?.comment.archivedAt).not.toBeNull();
    expect(node?.replies.map((r) => r.id)).toEqual([reply.id]);
  });

  it("scopes the thread to the organization, not just the issue", async () => {
    await expect(
      commentRepo.listThread(acme.org.id, northIssue.id),
    ).resolves.toEqual([]);
  });

  it("joins the author user record onto each comment", async () => {
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(north.org.id, north.project.id, { title: "Author join" }),
      north.userIds.owner,
      number,
    );
    await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "Authored",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.member,
    );

    const page = await commentRepo.listComments({
      orgId: north.org.id,
      issueId: issue.id,
      limit: 25,
      cursor: null,
      includeArchived: false,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.author.id).toBe(north.userIds.member);
    expect(page.items[0]?.author.email).toBe(`member@northwind-comments.test`);
  });
});
/**
 * Result envelope every job returns to the scheduler.
 */
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type JobResult = {
  kind: string;
  processed: number;
  failed: number;
  durationMs: number;
  startedAt: IsoTimestamp;
};

/** The zero value a job starts from and mutates as it works. */
export function emptyJobResult(
  kind: string,
  startedAt: IsoTimestamp,
): JobResult {
  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };
}

/**
 * Convenience for a job body: stamps the start, runs the work and fills in
 * `durationMs`. Kept here so every job reports the same shape.
 */
export async function runJob(
  kind: string,
  work: (result: JobResult) => Promise<void>,
): Promise<JobResult> {
  const startedAt = toIsoTimestamp(new Date());
  const began = Date.now();
  const result = emptyJobResult(kind, startedAt);

  await work(result);

  return { ...result, durationMs: Date.now() - began };
}
import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const webhookEndpoints = sqliteTable(
  "webhook_endpoints",
  {
    id: idColumn(),
    ...tenantColumns,
    url: text("url").notNull(),
    secret: text("secret").notNull(),
    /** JSON array of `TaskflowEventType`. */
    eventTypes: text("event_types").notNull().default("[]"),
    enabled: integer("enabled", { mode: "boolean" }).notNull().default(true),
    ...timestampColumns,
  },
  (table) => [index("webhook_endpoints_org_idx").on(table.orgId)],
);

export const webhookDeliveries = sqliteTable(
  "webhook_deliveries",
  {
    id: idColumn(),
    ...tenantColumns,
    endpointId: text("endpoint_id").notNull(),
    eventType: text("event_type").notNull(),
    payload: text("payload").notNull(),
    status: text("status", { enum: ["pending", "delivered", "failed"] })
      .notNull()
      .default("pending"),
    attempts: integer("attempts").notNull().default(0),
    lastError: text("last_error"),
    deliveredAt: text("delivered_at"),
    ...timestampColumns,
  },
  (table) => [
    index("webhook_deliveries_org_status_idx").on(table.orgId, table.status),
  ],
);

/** Token-bucket state for `src/lib/rate-limit.ts`, persisted per org+key. */
export const rateLimitBuckets = sqliteTable(
  "rate_limit_buckets",
  {
    id: idColumn(),
    ...tenantColumns,
    bucketKey: text("bucket_key").notNull(),
    tokens: integer("tokens").notNull(),
    refilledAt: text("refilled_at").notNull(),
  },
  (table) => [index("rate_limit_org_key_idx").on(table.orgId, table.bucketKey)],
);

/** Denormalised full-text index maintained by `SearchService`. */
export const searchIndex = sqliteTable(
  "search_index",
  {
    id: idColumn(),
    ...tenantColumns,
    subjectKind: text("subject_kind", {
      enum: ["issue", "comment", "project"],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    content: text("content").notNull(),
    indexedAt: text("indexed_at").notNull(),
  },
  (table) => [
    index("search_index_org_kind_idx").on(table.orgId, table.subjectKind),
  ],
);

export type WebhookEndpointRow = typeof webhookEndpoints.$inferSelect;
export type WebhookDeliveryRow = typeof webhookDeliveries.$inferSelect;
export type SearchIndexRow = typeof searchIndex.$inferSelect;
